const defaultState={language:'vi',page:'home',previous:'home',game:'jigsaw',category:'Tất cả',query:'',credits:0,loggedIn:false,phone:'',favorites:[],played:[],scores:[],joined:false,packageName:'Gói trải nghiệm',transactions:[],selectedPackage:20,paymentMethod:'MoMo',paymentStage:'idle',authStep:'phone',returnAfterLogin:'home',packageTermsAccepted:false,confirmTermsAccepted:false};
let state={...defaultState};
