const rankNumber=n=>Number(n).toLocaleString('en-US');
const rankArt=g=>GAME_ART[g.id]||A(g.art);
const rankGameName=g=>g.name;
function rankNavigate(page){state.rankStack=state.rankStack||[];if(state.page!==page)state.rankStack.push(state.page);go(page)}
function rankBack(){const dest=(state.rankStack||[]).pop()||'leaderboard';go(dest)}
function rankSvg(name){const icons={
clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',
game:'<path d="M6 7h12a4 4 0 0 1 4 3l1 5a3 3 0 0 1-5 3l-3-2H9l-3 2a3 3 0 0 1-5-3l1-5a4 4 0 0 1 4-3Z"/><path d="M7 10v5M4.5 12.5h5"/><circle cx="17" cy="11" r=".8"/><circle cx="19" cy="13" r=".8"/>',
trophy:'<path d="M7 3h10v8a5 5 0 0 1-10 0Z"/><path d="M7 5H4a2 2 0 0 0 0 4h3m10-4h3a2 2 0 0 1 0 4h-3M12 16v4m-4 1h8"/>',
calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',
location:'<path d="M20 10c0 5-8 12-8 12S4 15 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',
chart:'<path d="M5 20v-6m7 6V9m7 11V4"/>',
star:'<path d="m12 2 3 6 6.7 1-4.8 4.7 1.2 6.7L12 17l-6.1 3.4 1.2-6.7L2.3 9 9 8Z"/>',
chevron:'<path d="m9 5 7 7-7 7"/>',
check:'<path d="m5 12 4 4L19 6"/>'
};return `<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.star}</svg>`}
function rankTop(title,subtitle='',backButton=false,history=true){const en=state.language==='en';return `<div class="rank-heading">${backButton?`<button class="rank-back" data-rank-back aria-label="${en?'Back':'Quay lại'}">‹</button>`:''}<div class="rank-heading-text"><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${history?`<button class="rank-history-link" data-rank-go="rankHistory">${rankSvg('clock')} <span>${en?'Ranking History':'Lịch sử xếp hạng'}</span> ${rankSvg('chevron')}</button>`:''}</div>`}
function rankTabs(key,values){return `<div class="rank-tabs">${values.map(([value,label,ico])=>`<button class="${(state[key]||values[0][0])===value?'selected':''}" data-rank-setting="${key}" data-rank-value="${value}">${ico?rankSvg(ico):''}${label}</button>`).join('')}</div>`}
function rankBoardRows(count=5,kind='game'){const en=state.language==='en';const rows=rankPeople.slice(0,count);return `<div class="rank-table"><div class="rank-table-head"><span>#</span><span>${en?'Player':'Người chơi'}</span><span>${en?'Total Score':'Tổng điểm'}</span>${kind==='detail'?`<span>${en?'Achieved At':'Thời gian đạt'}</span>`:''}</div>${rows.map((p,i)=>`<div class="rank-table-row"><span class="rank-index">${i+4}</span><img src="${A(p.avatar)}" alt=""><span class="rank-person">${p.name}</span><strong>${rankNumber(kind==='tournament'?Math.round(p.score*.265):p.score)}</strong>${kind==='detail'?`<small>12/10 20:14</small>`:''}</div>`).join('')}<div class="rank-table-row me"><span class="rank-index">${kind==='detail'?12:8}</span><img src="${A('rank-avatar4')}" alt=""><span class="rank-person">${en?'You':'Bạn'} <small>✓ ${en?'Your position':'Vị trí của bạn'}</small></span><strong>${rankNumber(kind==='detail'?4580:10320)}</strong>${kind==='detail'?'<small>12/10 13:32</small>':''}</div></div>`}
function rankPodium(){return `<div class="rank-podium"><img src="${A('rank-podium')}" alt="Top 3: Minh Anh hạng 2, Hoàng Nam hạng 1, Tuấn Kiệt hạng 3"></div>`}
function rankGameCards(){const en=state.language==='en';return `<div class="rank-game-cards">${rankGames.slice(0,3).map((g,i)=>`<button class="rank-game-card" data-rank-game="${g.id}"><img src="${rankArt(g)}" alt="${g.name}"><div><strong>${g.name}</strong><small>${g.players==='—'?'—':g.players} ${en?'players':'người chơi'}</small></div><span class="rank-game-crown">♛ #${i+1}</span><span class="rank-game-view">${en?'View Details':'Xem chi tiết'} ›</span></button>`).join('')}</div>`}
function leaderboard(){const en=state.language==='en';return `<div class="rank-page">${rankTop(en?'Leaderboard':'Bảng xếp hạng',en?'Discover the top players<br>in the WiiG community':'Khám phá những người chơi xuất sắc nhất<br>trong cộng đồng WiiG')}${rankTabs('rankCategory',[['game',en?'Games':'Trò chơi','game'],['tournament',en?'Tournaments':'Giải đấu','trophy']])}${rankTabs('rankPeriod',[['week',en?'This Week':'Trong tuần'],['month',en?'This Month':'Trong tháng'],['quarter',en?'This Quarter':'Trong quý']])}<div class="rank-section-top"><strong>👑 ${en?'Top Players This Week':'Top người chơi tuần'}</strong><small>${rankSvg('clock')} ${en?'Updated Oct 12, 2026 at 21:00':'Cập nhật lúc 12/10/2026 21:00'}</small></div>${rankPodium()}${rankBoardRows(5)}<button class="rank-outline-btn" data-rank-go="rankGame">${en?'Game Leaderboards':'Xem bảng xếp hạng trò chơi'} ${rankSvg('chevron')}</button><div class="rank-subtitle"><h3>${en?'Rankings by Game':'Bảng xếp hạng theo trò chơi'}</h3><button data-rank-go="rankGame">${en?'View All':'Xem tất cả'} ${rankSvg('chevron')}</button></div>${rankGameCards()}<button class="rank-tournament-card" data-rank-go="rankTournament"><span class="rank-tournament-symbol">${rankSvg('trophy')}</span><span><strong>${en?'Tournament Leaderboard':'Bảng xếp hạng giải đấu'}</strong><small>${en?'See the top players in tournaments':'Xem những người chơi xuất sắc nhất tại các giải đấu'}</small></span>${rankSvg('chevron')}</button></div>`}
function rankGame(){const en=state.language==='en';const g=rankGames.find(g=>g.id===state.rankGame)||rankGames[0];return `<div class="rank-page">${rankTop((en?'Rankings: ':'Xếp hạng ')+g.name,'',true)}<div class="rank-selectors"><label><img src="${rankArt(g)}" alt="${g.name}"><select id="rank-game-select">${rankGames.map(x=>`<option value="${x.id}" ${g.id===x.id?'selected':''}>${x.name}</option>`).join('')}</select></label><label>${rankSvg('location')}<select id="rank-region-select"><option>${en?'Vietnam':'Việt Nam'}</option><option>${en?'Global':'Toàn cầu'}</option><option>${en?'Thailand':'Thái Lan'}</option></select></label></div>${rankTabs('rankPeriod',[['week',en?'This Week':'Tuần này'],['month',en?'This Month':'Tháng này'],['quarter',en?'This Quarter':'Quý này']])}<div class="rank-dates">${rankSvg('calendar')} ${en?'Period: Oct 6, 2026 – Oct 12, 2026':'Thời gian: 06/10/2026 - 12/10/2026'} <span>♕ ${en?'Ranked by total score':'Xếp hạng theo tổng điểm'}</span></div>${rankPodium()}${rankBoardRows(8,'detail')}<button class="rank-outline-btn" data-rank-more>${en?'Load More Rankings':'Xem thêm bảng xếp hạng'} ⌄</button></div>`}
function rankTournament(){const en=state.language==='en';return `<div class="rank-page">${rankTop('Speed Challenge',en?'Tournament Leaderboard':'Bảng xếp hạng giải đấu',true)}<div class="rank-challenge"><img src="${A('rank-space')}" alt=""><div><span class="rank-live">● ${en?'LIVE NOW':'ĐANG DIỄN RA'}</span><h2>Jigsaw Puzzle<br>Speed Challenge</h2><p>${en?'Race against time and aim for the highest score!':'Thử thách tốc độ, chinh phục điểm số cao nhất!'}</p></div><div class="rank-countdown">${rankSvg('clock')} ${en?'Ends in':'Kết thúc sau'}<br><strong>2 days 12:30:45</strong></div></div><div class="rank-dates">${rankSvg('calendar')} ${en?'This Week · Oct 6–12, 2026':'Tuần này · 06/10 - 12/10/2026'}</div><div class="rank-podium"><img src="${A('rank-podium-plain')}" alt="Top three players in Speed Challenge"></div>${rankBoardRows(7,'tournament')}<div class="rank-my-position">${rankSvg('chart')}<span>${en?'Your Rank':'Hạng của bạn'}: <strong>#8</strong><small>High Score: 4,900 ${en?'points':'điểm'}</small></span><button data-rank-go="rankHistory">${en?'Up 2 places':'Tăng 2 hạng'} ›</button></div><button class="rank-main-btn" data-action="join">${rankSvg('game')} ${state.joined?(en?'Continue Playing':'Thi đấu tiếp'):(en?'Join Tournament':'Tham gia giải đấu')} ${rankSvg('chevron')}</button></div>`}
function rankHistory(){const en=state.language==='en';const type=state.rankHistoryCategory||'game';return `<div class="rank-page">${rankTop(en?'Ranking History':'Lịch sử xếp hạng',en?'Review results from completed ranking periods':'Xem kết quả các kỳ xếp hạng đã kết thúc',true,false)}${rankTabs('rankHistoryCategory',[['game',en?'Games':'Trò chơi','game'],['tournament',en?'Tournaments':'Giải đấu','trophy']])}${rankTabs('rankPeriod',[['week',en?'Week':'Tuần'],['month',en?'Month':'Tháng'],['quarter',en?'Quarter':'Quý']])}<div class="rank-history-list">${rankGames.map((g,i)=>`<article class="rank-history-card"><div class="rank-history-card-head"><img src="${rankArt(g)}" alt="${g.name}"><div><strong>${type==='tournament'?g.name+' Challenge':g.name}</strong><small>${en?'Week':'Tuần'} ${['06/10/2026 - 12/10/2026','29/09/2026 - 05/10/2026'][i%2]}</small></div><span class="rank-done">${rankSvg('check')} ${en?'Finalized':'Đã chốt'}</span><button data-rank-game="${g.id}" aria-label="${en?'View leaderboard':'Xem bảng xếp hạng'}">${rankSvg('chevron')}</button></div><div class="rank-history-stats"><div>${rankSvg('star')}<span>${en?'Your Score':'Điểm của bạn'}<strong>${rankNumber(g.score)}</strong></span></div><div>${rankSvg('chart')}<span>${en?'Your Rank':'Hạng của bạn'}<strong>#${g.place}</strong></span></div><button data-rank-game="${g.id}">${en?'View Board':'Xem bảng'} ›</button></div></article>`).join('')}</div></div>`}
const purchaseOptions=[{count:10,price:25000,art:'pkg10',tag:'',desc:'Trải nghiệm game mỗi ngày'},{count:20,price:45000,art:'pkg20',tag:'',desc:'Thêm lượt chơi hấp dẫn'},{count:50,price:99000,art:'pkg50',tag:'Phổ biến nhất',desc:'Chơi thỏa thích hơn'}];
